Your expense tracker is below: add an expense with a date, category and amount, and it updates your total, category split and what's left of your budget. Entries stay only while this page is open, so they reset when you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
h1{font-size:20px;margin:0 0 12px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
.row{display:flex;gap:8px;flex-wrap:wrap;align-items:end}
label{font-size:12px;color:#666;display:flex;flex-direction:column;gap:3px}
input,select,button{font:inherit;padding:6px 8px;border:1px solid #ccc;border-radius:6px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#c00;padding:2px 8px}
.big{font-size:24px;font-weight:600}
.bar{height:10px;background:#e3e3ea;border-radius:5px;overflow:hidden;margin:3px 0 8px}
.bar i{display:block;height:100%;background:#2b6cb0}
.over i{background:#c53030}
table{width:100%;border-collapse:collapse;font-size:14px}
td{padding:6px 4px;border-bottom:1px solid #eee}
td.r{text-align:right}
.muted{color:#777;font-size:13px}
</style></head><body>
<h1>Monthly expense tracker</h1>

<div class="card row">
<label>Month<input type="month" id="month"></label>
<label>Budget (₹)<input type="number" id="budget" value="50000" min="0"></label>
</div>

<div class="card">
<div class="muted">Spent this month</div>
<div class="big" id="total">₹0</div>
<div class="bar" id="budgetBar"><i style="width:0%"></i></div>
<div class="muted" id="left"></div>
</div>

<div class="card row">
<label>Date<input type="date" id="date"></label>
<label>Category<select id="cat">
<option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option>
<option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
</select></label>
<label>Amount (₹)<input type="number" id="amt" min="0" placeholder="0"></label>
<label>Note<input type="text" id="note" placeholder="Optional"></label>
<button id="add" type="button">Add</button>
</div>

<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>

<div class="card"><b>Expenses</b>
<table id="list"></table>
<div class="muted" id="empty">Nothing added for this month yet.</div>
</div>

<script>
var items=[];
var $=function(i){return document.getElementById(i)};
var fmt=function(n){return "₹"+Math.round(n).toLocaleString("en-IN")};
$("date").value="2026-10-24";
$("month").value="2026-10";

function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}

function render(){
  var m=$("month").value;
  var shown=items.filter(function(e){return e.date.slice(0,7)===m})
    .sort(function(a,b){return a.date<b.date?1:-1});
  var total=shown.reduce(function(s,e){return s+e.amt},0);
  var budget=parseFloat($("budget").value)||0;
  $("total").textContent=fmt(total);
  var pct=budget>0?Math.min(100,total/budget*100):0;
  $("budgetBar").className="bar"+(budget>0&&total>budget?" over":"");
  $("budgetBar").firstChild.style.width=pct+"%";
  $("left").textContent=budget>0
    ?(total>budget?"Over budget by "+fmt(total-budget):fmt(budget-total)+" left of "+fmt(budget))
    :"Set a budget to see what is left";

  var by={};
  shown.forEach(function(e){by[e.cat]=(by[e.cat]||0)+e.amt});
  var html="";
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
    html+="<div class='row' style='justify-content:space-between'><span>"+esc(k)+"</span><span>"+fmt(by[k])+"</span></div>"
      +"<div class='bar'><i style='width:"+(by[k]/total*100)+"%'></i></div>";
  });
  $("cats").innerHTML=html||"<span class='muted'>No spending yet.</span>";

  var rows="";
  shown.forEach(function(e){
    rows+="<tr><td>"+esc(e.date)+"</td><td>"+esc(e.cat)+"</td><td>"+esc(e.note)+"</td><td class='r'>"+fmt(e.amt)
      +"</td><td><button class='x' type='button' data-id='"+e.id+"'>✕</button></td></tr>";
  });
  $("list").innerHTML=rows;
  $("empty").style.display=shown.length?"none":"block";
}

var nextId=1;
$("add").onclick=function(){
  var a=parseFloat($("amt").value);
  if(!a||a<=0||!$("date").value){return}
  items.push({id:nextId++,date:$("date").value,cat:$("cat").value,amt:a,note:$("note").value});
  $("amt").value="";$("note").value="";
  $("month").value=items[items.length-1].date.slice(0,7);
  render();
};
$("list").onclick=function(ev){
  var id=ev.target.getAttribute&&ev.target.getAttribute("data-id");
  if(id){items=items.filter(function(e){return e.id!==+id});render()}
};
$("month").onchange=render;
$("budget").oninput=render;
render();
</script>
</body></html>
```

