Here's a water tracker with a goal of 8 glasses. Tap a glass to fill it, tap again to undo, and it saves on this PC for today.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; text-align: center; padding: 24px; margin: 0; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  #count { font-size: 40px; font-weight: 600; margin: 12px 0 4px; }
  #msg { color: #666; margin-bottom: 16px; min-height: 20px; }
  #bar { height: 10px; background: #e5e7eb; border-radius: 5px; overflow: hidden; max-width: 320px; margin: 0 auto 20px; }
  #fill { height: 100%; width: 0; background: #2f8fe0; transition: width .25s; }
  #glasses { display: grid; grid-template-columns: repeat(4, 56px); gap: 12px; justify-content: center; margin-bottom: 20px; }
  .g { width: 56px; height: 72px; border: 2px solid #2f8fe0; border-radius: 4px 4px 14px 14px; background: #fff; cursor: pointer; padding: 0; }
  .g.on { background: #2f8fe0; }
  button.r { border: 0; background: none; color: #666; text-decoration: underline; cursor: pointer; font-size: 14px; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <button class="r" id="reset">Start over</button>
<script>
  var GOAL = 8;
  var today = new Date().toDateString();
  var n = 0;
  try {
    var s = JSON.parse(localStorage.getItem("water") || "{}");
    if (s.day === today) n = s.n;
  } catch (e) {}
  document.getElementById("date").textContent = today;

  var box = document.getElementById("glasses");
  var cups = [];
  for (var i = 0; i < GOAL; i++) {
    (function (i) {
      var b = document.createElement("button");
      b.className = "g";
      b.setAttribute("aria-label", "Glass " + (i + 1));
      b.onclick = function () { n = (n === i + 1) ? i : i + 1; draw(); };
      box.appendChild(b);
      cups.push(b);
    })(i);
  }
  document.getElementById("reset").onclick = function () { n = 0; draw(); };

  function draw() {
    cups.forEach(function (c, i) { c.className = "g" + (i < n ? " on" : ""); });
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
    try { localStorage.setItem("water", JSON.stringify({ day: today, n: n })); } catch (e) {}
  }
  draw();
</script>
</body>
</html>
```
